/* ---- static helpers ---- */

static void gen_state_free(void *p) {
    free(p);
}

/* ---- save hooks (F2j-2 slots, consumed by csrc/save.c) ----
 * Explicit little-endian scalars, no struct memcpy. Only the used prefix of
 * each array is written (n_characters, n_lineages, n_force, n_deaths, ...);
 * everything past it is zero in a live state, so a read into a calloc'd
 * state reproduces it byte for byte. A world with no allocated state writes
 * a 0-byte blob. See also: csrc/save.c sv_write_slots -- calls these. */

#define GEN_ONBOARDING_ARRAY_LEN ((uint32_t)(sizeof(((om_onboarding_config *)0)->weights) / sizeof(double)))

typedef struct {
    uint8_t *buf; /* NULL: size-only pass */
    uint32_t pos;
} gen_sw;

static void gen_sw_uint(gen_sw *sw, uint64_t v, uint32_t width) {
    if (sw->buf) {
        for (uint32_t i = 0; i < width; i++)
            sw->buf[sw->pos + i] = (uint8_t)((v >> (OM_SAVE_BYTE_BITS * i)) & OM_SAVE_BYTE_MASK);
    }
    sw->pos += width;
}
static void gen_sw_u8(gen_sw *sw, uint32_t v) { gen_sw_uint(sw, v, (uint32_t)sizeof(uint8_t)); }
static void gen_sw_u32(gen_sw *sw, uint32_t v) { gen_sw_uint(sw, v, (uint32_t)sizeof(uint32_t)); }
static void gen_sw_u64(gen_sw *sw, uint64_t v) { gen_sw_uint(sw, v, (uint32_t)sizeof(uint64_t)); }
static void gen_sw_i32(gen_sw *sw, int32_t v) { gen_sw_uint(sw, (uint32_t)v, (uint32_t)sizeof(int32_t)); }
static void gen_sw_f64(gen_sw *sw, double v) {
    uint64_t bits;
    memcpy(&bits, &v, sizeof(bits));
    gen_sw_u64(sw, bits);
}
static void gen_sw_bytes(gen_sw *sw, const char *src, uint32_t n) {
    if (sw->buf) memcpy(sw->buf + sw->pos, src, n);
    sw->pos += n;
}

static void gen_state_put(gen_sw *sw, const gen_state *gs) {
    gen_sw_u32(sw, gs->n_characters);
    for (uint32_t i = 0; i < gs->n_characters; i++) {
        const gen_character *c = &gs->characters[i];
        gen_sw_u8(sw, (uint32_t)c->used);
        gen_sw_u32(sw, c->id);
        gen_sw_bytes(sw, c->name, (uint32_t)sizeof(c->name));
        gen_sw_i32(sw, c->faction);
        gen_sw_u32(sw, c->region);
        gen_sw_u32(sw, c->rank);
        gen_sw_u64(sw, c->birth_tick);
        gen_sw_u32(sw, c->lifespan);
        gen_sw_u32(sw, c->status);
        gen_sw_u64(sw, c->death_tick);
        gen_sw_u32(sw, c->lineage_id);
        gen_sw_u32(sw, c->parent_id);
        gen_sw_u32(sw, c->generation);
        for (uint32_t k = 0; k < GEN_MAX_RIVAL_TAGS; k++) gen_sw_u32(sw, c->rival_of[k]);
        gen_sw_u32(sw, c->n_rival_of);
        gen_sw_u32(sw, c->n_children);
        gen_sw_u8(sw, (uint32_t)c->is_main_character);
    }
    gen_sw_u32(sw, gs->next_auto_id);

    gen_sw_u32(sw, gs->n_lineages);
    for (uint32_t i = 0; i < gs->n_lineages; i++) {
        const gen_lineage *l = &gs->lineages[i];
        gen_sw_u8(sw, (uint32_t)l->used);
        gen_sw_u32(sw, l->id);
        for (uint32_t k = 0; k < GEN_MAX_LINEAGE_HISTORY; k++) gen_sw_u32(sw, l->history[k]);
        gen_sw_u32(sw, l->n_history);
        gen_sw_u32(sw, l->chapter_count);
    }

    for (uint32_t i = 0; i < OM_MAX_FACTIONS; i++) gen_sw_u32(sw, gs->supreme_commander[i]);
    for (uint32_t i = 0; i < GEN_REGION_CAP; i++) gen_sw_u32(sw, gs->regional_commander[i]);
    for (uint32_t i = 0; i < OM_MAX_FACTIONS; i++) gen_sw_i32(sw, gs->faction_fallen[i]);

    gen_sw_u32(sw, gs->n_force);
    for (uint32_t i = 0; i < gs->n_force; i++) {
        const gen_force *f = &gs->force[i];
        gen_sw_u8(sw, (uint32_t)f->used);
        gen_sw_u32(sw, f->mission_id);
        gen_sw_f64(sw, f->budget);
        gen_sw_u32(sw, f->survivors);
        gen_sw_u32(sw, f->allocated);
    }

    for (uint32_t i = 0; i < GEN_MAX_ONBOARDING_SLOTS; i++) {
        gen_sw_u8(sw, (uint32_t)gs->onboarding_used[i]);
        const om_onboarding_config *o = &gs->onboarding[i];
        gen_sw_u32(sw, o->difficulty);
        for (uint32_t k = 0; k < GEN_ONBOARDING_ARRAY_LEN; k++) gen_sw_f64(sw, o->weights[k]);
        for (uint32_t k = 0; k < GEN_ONBOARDING_ARRAY_LEN; k++) gen_sw_u32(sw, o->rare_marks[k]);
    }

    gen_sw_u32(sw, gs->n_deaths);
    for (uint32_t i = 0; i < gs->n_deaths; i++) {
        const gen_death_rec *d = &gs->deaths[i];
        gen_sw_u8(sw, (uint32_t)d->used);
        gen_sw_u32(sw, d->commander_id);
        gen_sw_u32(sw, d->region);
        gen_sw_i32(sw, d->band);
    }

    gen_sw_u32(sw, gs->n_nemesis_candidates);
    for (uint32_t i = 0; i < gs->n_nemesis_candidates; i++) gen_sw_u32(sw, gs->nemesis_candidates[i]);

    gen_sw_u8(sw, (uint32_t)gs->pool_previous_forced_empty);
    gen_sw_u8(sw, (uint32_t)gs->pool_nemesis_forced_empty);
    gen_sw_i32(sw, gs->chapter_phase);
    gen_sw_u32(sw, gs->chapter_number);
    gen_sw_u8(sw, (uint32_t)gs->needs_onboarding);
    gen_sw_u8(sw, (uint32_t)gs->in_transition);
    gen_sw_u32(sw, gs->death_pass_count);
    gen_sw_u64(sw, gs->time_jump_lineage_gen_tick);
    gen_sw_u64(sw, gs->time_jump_death_tick);
    gen_sw_u32(sw, gs->mission_chosen_region);
    gen_sw_u32(sw, gs->selector_input_region);
    gen_sw_u8(sw, (uint32_t)gs->consequence_consumed);
    gen_sw_u32(sw, gs->current_commander);
    gen_sw_u32(sw, gs->current_lineage);
    gen_sw_i32(sw, gs->chosen_archetype);
    gen_sw_u8(sw, (uint32_t)gs->has_candidate);
    gen_sw_i32(sw, gs->last_end_reason);
}

typedef struct {
    const uint8_t *p;
    uint32_t len;
    uint32_t pos;
    int ok;
} gen_sr;

static uint64_t gen_sr_uint(gen_sr *sr, uint32_t width) {
    if (!sr->ok || width > sr->len - sr->pos) {
        sr->ok = 0;
        return 0;
    }
    uint64_t v = 0;
    for (uint32_t i = 0; i < width; i++) v |= ((uint64_t)sr->p[sr->pos + i]) << (OM_SAVE_BYTE_BITS * i);
    sr->pos += width;
    return v;
}
static uint32_t gen_sr_u8(gen_sr *sr) { return (uint32_t)gen_sr_uint(sr, (uint32_t)sizeof(uint8_t)); }
static uint32_t gen_sr_u32(gen_sr *sr) { return (uint32_t)gen_sr_uint(sr, (uint32_t)sizeof(uint32_t)); }
static uint64_t gen_sr_u64(gen_sr *sr) { return gen_sr_uint(sr, (uint32_t)sizeof(uint64_t)); }
static int32_t gen_sr_i32(gen_sr *sr) { return (int32_t)gen_sr_uint(sr, (uint32_t)sizeof(int32_t)); }
static double gen_sr_f64(gen_sr *sr) {
    uint64_t bits = gen_sr_u64(sr);
    double v;
    memcpy(&v, &bits, sizeof(v));
    return v;
}
static uint32_t gen_sr_count(gen_sr *sr, uint32_t cap) {
    uint32_t n = gen_sr_u32(sr);
    if (n > cap) {
        sr->ok = 0;
        return 0;
    }
    return n;
}
static uint32_t gen_sr_flag(gen_sr *sr) {
    uint32_t v = gen_sr_u8(sr);
    if (v > 1) sr->ok = 0;
    return v;
}

static void gen_state_get(gen_sr *sr, gen_state *gs) {
    gs->n_characters = gen_sr_count(sr, GEN_MAX_CHARACTERS);
    for (uint32_t i = 0; i < gs->n_characters && sr->ok; i++) {
        gen_character *c = &gs->characters[i];
        c->used = (int)gen_sr_flag(sr);
        c->id = gen_sr_u32(sr);
        if (sr->ok && sizeof(c->name) <= sr->len - sr->pos) {
            memcpy(c->name, sr->p + sr->pos, sizeof(c->name));
            sr->pos += (uint32_t)sizeof(c->name);
            c->name[sizeof(c->name) - 1] = '\0';
        } else {
            sr->ok = 0;
        }
        c->faction = gen_sr_i32(sr);
        c->region = gen_sr_u32(sr);
        c->rank = gen_sr_u32(sr);
        c->birth_tick = gen_sr_u64(sr);
        c->lifespan = gen_sr_u32(sr);
        c->status = gen_sr_u32(sr);
        c->death_tick = gen_sr_u64(sr);
        c->lineage_id = gen_sr_u32(sr);
        c->parent_id = gen_sr_u32(sr);
        c->generation = gen_sr_u32(sr);
        for (uint32_t k = 0; k < GEN_MAX_RIVAL_TAGS; k++) c->rival_of[k] = gen_sr_u32(sr);
        c->n_rival_of = gen_sr_u32(sr);
        if (c->n_rival_of > GEN_MAX_RIVAL_TAGS) sr->ok = 0;
        c->n_children = gen_sr_u32(sr);
        c->is_main_character = (int)gen_sr_flag(sr);
    }
    gs->next_auto_id = gen_sr_u32(sr);

    gs->n_lineages = gen_sr_count(sr, GEN_MAX_LINEAGES);
    for (uint32_t i = 0; i < gs->n_lineages && sr->ok; i++) {
        gen_lineage *l = &gs->lineages[i];
        l->used = (int)gen_sr_flag(sr);
        l->id = gen_sr_u32(sr);
        for (uint32_t k = 0; k < GEN_MAX_LINEAGE_HISTORY; k++) l->history[k] = gen_sr_u32(sr);
        l->n_history = gen_sr_u32(sr);
        if (l->n_history > GEN_MAX_LINEAGE_HISTORY) sr->ok = 0;
        l->chapter_count = gen_sr_u32(sr);
    }

    for (uint32_t i = 0; i < OM_MAX_FACTIONS; i++) gs->supreme_commander[i] = gen_sr_u32(sr);
    for (uint32_t i = 0; i < GEN_REGION_CAP; i++) gs->regional_commander[i] = gen_sr_u32(sr);
    for (uint32_t i = 0; i < OM_MAX_FACTIONS; i++) gs->faction_fallen[i] = gen_sr_i32(sr);

    gs->n_force = gen_sr_count(sr, GEN_MAX_FORCE_MISSIONS);
    for (uint32_t i = 0; i < gs->n_force && sr->ok; i++) {
        gen_force *f = &gs->force[i];
        f->used = (int)gen_sr_flag(sr);
        f->mission_id = gen_sr_u32(sr);
        f->budget = gen_sr_f64(sr);
        f->survivors = gen_sr_u32(sr);
        f->allocated = gen_sr_u32(sr);
    }

    for (uint32_t i = 0; i < GEN_MAX_ONBOARDING_SLOTS && sr->ok; i++) {
        gs->onboarding_used[i] = (int)gen_sr_flag(sr);
        om_onboarding_config *o = &gs->onboarding[i];
        o->difficulty = gen_sr_u32(sr);
        for (uint32_t k = 0; k < GEN_ONBOARDING_ARRAY_LEN; k++) o->weights[k] = gen_sr_f64(sr);
        for (uint32_t k = 0; k < GEN_ONBOARDING_ARRAY_LEN; k++) o->rare_marks[k] = gen_sr_u32(sr);
    }

    gs->n_deaths = gen_sr_count(sr, GEN_MAX_DEATH_RECORDS);
    for (uint32_t i = 0; i < gs->n_deaths && sr->ok; i++) {
        gen_death_rec *d = &gs->deaths[i];
        d->used = (int)gen_sr_flag(sr);
        d->commander_id = gen_sr_u32(sr);
        d->region = gen_sr_u32(sr);
        d->band = gen_sr_i32(sr);
    }

    gs->n_nemesis_candidates = gen_sr_count(sr, GEN_MAX_NEMESIS_CANDIDATES);
    for (uint32_t i = 0; i < gs->n_nemesis_candidates && sr->ok; i++) gs->nemesis_candidates[i] = gen_sr_u32(sr);

    gs->pool_previous_forced_empty = (int)gen_sr_flag(sr);
    gs->pool_nemesis_forced_empty = (int)gen_sr_flag(sr);
    gs->chapter_phase = gen_sr_i32(sr);
    gs->chapter_number = gen_sr_u32(sr);
    gs->needs_onboarding = (int)gen_sr_flag(sr);
    gs->in_transition = (int)gen_sr_flag(sr);
    gs->death_pass_count = gen_sr_u32(sr);
    gs->time_jump_lineage_gen_tick = gen_sr_u64(sr);
    gs->time_jump_death_tick = gen_sr_u64(sr);
    gs->mission_chosen_region = gen_sr_u32(sr);
    gs->selector_input_region = gen_sr_u32(sr);
    gs->consequence_consumed = (int)gen_sr_flag(sr);
    gs->current_commander = gen_sr_u32(sr);
    gs->current_lineage = gen_sr_u32(sr);
    gs->chosen_archetype = gen_sr_i32(sr);
    gs->has_candidate = (int)gen_sr_flag(sr);
    gs->last_end_reason = gen_sr_i32(sr);
}

/* A state nothing has written to (allocated lazily by any accessor, including
 * the per-tick hooks) carries no information: it saves as an empty blob and
 * comes back lazily on the next access, the same as a world that never
 * touched this module. */
static int gen_state_pristine(const gen_state *gs) {
    if (gs->n_characters || gs->n_lineages || gs->n_force || gs->n_deaths || gs->n_nemesis_candidates) return 0;
    if (gs->next_auto_id != GEN_AUTO_ID_BASE) return 0;
    if (gs->pool_previous_forced_empty || gs->pool_nemesis_forced_empty) return 0;
    if (gs->chapter_phase || gs->chapter_number || gs->needs_onboarding || gs->in_transition) return 0;
    if (gs->death_pass_count || gs->time_jump_lineage_gen_tick || gs->time_jump_death_tick) return 0;
    if (gs->mission_chosen_region || gs->selector_input_region || gs->consequence_consumed) return 0;
    if (gs->current_commander || gs->current_lineage || gs->chosen_archetype || gs->has_candidate || gs->last_end_reason) return 0;
    for (uint32_t i = 0; i < OM_MAX_FACTIONS; i++)
        if (gs->supreme_commander[i] || gs->faction_fallen[i]) return 0;
    for (uint32_t i = 0; i < GEN_REGION_CAP; i++)
        if (gs->regional_commander[i]) return 0;
    for (uint32_t i = 0; i < GEN_MAX_ONBOARDING_SLOTS; i++)
        if (gs->onboarding_used[i]) return 0;
    return 1;
}

static uint32_t gen_state_size_hook(const om_world *w) {
    const gen_state *gs = (const gen_state *)w->generational_state;
    if (!gs || gen_state_pristine(gs)) return 0;
    gen_sw sw = { NULL, 0 };
    gen_state_put(&sw, gs);
    return sw.pos;
}

static void gen_state_write_hook(const om_world *w, uint8_t *out) {
    const gen_state *gs = (const gen_state *)w->generational_state;
    if (!gs || gen_state_pristine(gs)) return;
    gen_sw sw = { out, 0 };
    gen_state_put(&sw, gs);
}

static int gen_state_read_hook(om_world *w, const uint8_t *buf, uint32_t len) {
    if (len == 0) return 0;
    if (!buf) return 1;
    gen_state *gs = calloc(1, sizeof(gen_state));
    if (!gs) return 1;
    gen_sr sr = { buf, len, 0, 1 };
    gen_state_get(&sr, gs);
    if (!sr.ok || sr.pos != len) {
        free(gs);
        return 1;
    }
    if (w->generational_state) gen_state_free(w->generational_state);
    w->generational_state = gs;
    w->generational_state_free = gen_state_free;
    w->generational_state_size = gen_state_size_hook;
    w->generational_state_write = gen_state_write_hook;
    w->generational_state_read = gen_state_read_hook;
    return 0;
}

/* F2m (om_internal.h): wires the three save hooks onto a world that has not
 * yet allocated w->generational_state, so a fresh world's read hook is
 * never NULL (gen_state_read_hook above already copes with a NULL
 * generational_state / len == 0 by building fresh state or writing a
 * 0-length blob). Called once from om_world_new (csrc/region.c);
 * gen_get_state below sets the same three pointers again once state
 * actually exists, so this never allocates. */
void om_generational_install_save_hooks(om_world *w) {
    w->generational_state_size = gen_state_size_hook;
    w->generational_state_write = gen_state_write_hook;
    w->generational_state_read = gen_state_read_hook;
}

/* R-078-06 / architect rulings 2 section 1.3: 1 while the last mission has a known band and
 * its consequence is not yet consumed by a jump. */
int om_chronicle_has_mission_consequence_flag(const om_world *w) {
    const gen_state *gs = (const gen_state *)w->generational_state;
    if (gs && gs->consequence_consumed) return 0;
    return om_mission_get_band(w) != GEN_BAND_UNKNOWN;
}

/* See also: csrc/mission.c om_mission_end / om_mission_resolve_refusal call this: a new result
 * gets its own consequence in the next jump. Not declared in a header (mission.c declares it). */
void om_gen_consequence_rearm(om_world *w) {
    gen_state *gs = (gen_state *)w->generational_state;
    if (gs) gs->consequence_consumed = 0;
}

static gen_state *gen_get_state(const om_world *cw) {
    om_world *w = (om_world *)cw;
    if (!w) return NULL;
    if (!w->generational_state) {
        gen_state *gs = calloc(1, sizeof(gen_state));
        if (!gs) return NULL;
        gs->next_auto_id = GEN_AUTO_ID_BASE;
        w->generational_state = gs;
        w->generational_state_free = gen_state_free;
        w->generational_state_size = gen_state_size_hook;
        w->generational_state_write = gen_state_write_hook;
        w->generational_state_read = gen_state_read_hook;
    }
    return (gen_state *)w->generational_state;
}

static double gen_pow_int(double base, uint32_t exp) {
    double r = 1.0;
    for (uint32_t i = 0; i < exp; i++) r *= base;
    return r;
}

static uint32_t gen_roll_lifespan(om_world *w) {
    double d = om_rng_draw(w);
    uint32_t span = (uint32_t)(OM_LIFESPAN_MAX - OM_LIFESPAN_MIN + 1);
    uint32_t off = (uint32_t)(d * (double)span);
    if (off >= span) off = span - 1;
    return OM_LIFESPAN_MIN + off;
}

static void gen_roll_name(om_world *w, char *out, size_t cap) {
    double d = om_rng_draw(w);
    size_t n = sizeof(GEN_NAME_POOL) / sizeof(GEN_NAME_POOL[0]);
    size_t idx = (size_t)(d * (double)n);
    if (idx >= n) idx = n - 1;
    const char *src = GEN_NAME_POOL[idx];
    size_t i = 0;
    while (src[i] != '\0' && i + 1 < cap) { out[i] = src[i]; i++; }
    out[i] = '\0';
}

static gen_character *gen_char_find(gen_state *gs, uint32_t id) {
    if (!gs) return NULL;
    for (uint32_t i = 0; i < gs->n_characters; i++)
        if (gs->characters[i].used && gs->characters[i].id == id) return &gs->characters[i];
    return NULL;
}

static gen_character *gen_char_alloc(gen_state *gs, uint32_t id) {
    if (!gs) return NULL;
    gen_character *existing = gen_char_find(gs, id);
    if (existing) return existing;
    if (gs->n_characters >= GEN_MAX_CHARACTERS) return NULL;
    gen_character *c = &gs->characters[gs->n_characters++];
    memset(c, 0, sizeof(*c));
    c->used = 1;
    c->id = id;
    c->faction = -1;
    return c;
}

static uint32_t gen_alloc_id(gen_state *gs) {
    if (!gs) return 0;
    if (gs->next_auto_id < GEN_AUTO_ID_BASE) gs->next_auto_id = GEN_AUTO_ID_BASE;
    return gs->next_auto_id++;
}

static void gen_char_mark_main(gen_character *c) {
    if (c) c->is_main_character = 1;
}

static gen_lineage *gen_lineage_find(gen_state *gs, uint32_t id) {
    if (!gs) return NULL;
    for (uint32_t i = 0; i < gs->n_lineages; i++)
        if (gs->lineages[i].used && gs->lineages[i].id == id) return &gs->lineages[i];
    return NULL;
}

static gen_lineage *gen_lineage_alloc(gen_state *gs, uint32_t id) {
    if (!gs) return NULL;
    gen_lineage *e = gen_lineage_find(gs, id);
    if (e) return e;
    if (gs->n_lineages >= GEN_MAX_LINEAGES) return NULL;
    e = &gs->lineages[gs->n_lineages++];
    memset(e, 0, sizeof(*e));
    e->used = 1;
    e->id = id;
    return e;
}

static uint32_t gen_create_commander(om_world *w, gen_state *gs, int32_t faction_id, uint32_t region_idx, uint32_t rank) {
    uint32_t id = gen_alloc_id(gs);
    gen_character *c = gen_char_alloc(gs, id);
    if (!c) return 0;
    c->faction = faction_id;
    c->region = region_idx;
    c->rank = rank;
    c->birth_tick = w ? w->tick : 0;
    c->lifespan = gen_roll_lifespan(w);
    c->status = GEN_STATUS_ACTIVE;
    gen_roll_name(w, c->name, sizeof(c->name));
    return id;
}

static int gen_bfs_distance(const om_world *w, uint32_t from, uint32_t to, uint32_t max_hops) {
    if (!w || from >= w->n_regions || to >= w->n_regions) return -1;
    if (from == to) return 0;
    int dist[GEN_REGION_CAP];
    for (uint32_t i = 0; i < GEN_REGION_CAP; i++) dist[i] = -1;
    dist[from] = 0;
    uint32_t frontier[GEN_REGION_CAP];
    uint32_t n_frontier = 0;
    frontier[n_frontier++] = from;
    for (uint32_t hop = 0; hop < max_hops; hop++) {
        uint32_t next[GEN_REGION_CAP];
        uint32_t n_next = 0;
        for (uint32_t i = 0; i < n_frontier; i++) {
            uint32_t nbrs[GEN_REGION_CAP];
            uint32_t n_nbrs = om_region_neighbors(w, frontier[i], nbrs, GEN_REGION_CAP);
            for (uint32_t j = 0; j < n_nbrs; j++) {
                uint32_t r = nbrs[j];
                if (r < GEN_REGION_CAP && dist[r] == -1) {
                    dist[r] = (int)hop + 1;
                    next[n_next++] = r;
                }
            }
        }
        for (uint32_t i = 0; i < n_next; i++) frontier[i] = next[i];
        n_frontier = n_next;
        if (n_frontier == 0) break;
    }
    return dist[to];
}

static int gen_region_within_hops(const om_world *w, uint32_t from, uint32_t to, uint32_t max_hops) {
    return gen_bfs_distance(w, from, to, max_hops) >= 0;
}

static uint32_t gen_count_living_in_lineage(gen_state *gs, uint32_t lineage_id) {
    uint32_t n = 0;
    if (!gs) return 0;
    for (uint32_t i = 0; i < gs->n_characters; i++)
        if (gs->characters[i].used && gs->characters[i].lineage_id == lineage_id
            && gs->characters[i].status == GEN_STATUS_ACTIVE) n++;
    return n;
}

static uint32_t gen_living_members_of(gen_state *gs, uint32_t lineage_id, uint32_t *out, uint32_t max) {
    uint32_t n = 0;
    if (!gs) return 0;
    for (uint32_t i = 0; i < gs->n_characters && n < max; i++) {
        gen_character *c = &gs->characters[i];
        if (c->used && c->lineage_id == lineage_id && c->status == GEN_STATUS_ACTIVE) out[n++] = c->id;
    }
    return n;
}

static gen_character *gen_find_living_member_exact_hop(const om_world *w, gen_state *gs, uint32_t lineage_id,
                                                        uint32_t mission_region, uint32_t hop, int exclude_supreme) {
    if (!gs) return NULL;
    for (uint32_t i = 0; i < gs->n_characters; i++) {
        gen_character *c = &gs->characters[i];
        if (!c->used || c->lineage_id != lineage_id || c->status != GEN_STATUS_ACTIVE) continue;
        if (exclude_supreme && c->rank == GEN_RANK_SUPREME_COMMANDER) continue;
        if (gen_bfs_distance(w, mission_region, c->region, hop) == (int)hop) return c;
    }
    return NULL;
}

static int gen_find_living_member_within_hops(const om_world *w, gen_state *gs, uint32_t lineage_id,
                                               uint32_t mission_region, uint32_t max_hops, int exclude_supreme) {
    if (!gs) return 0;
    for (uint32_t i = 0; i < gs->n_characters; i++) {
        gen_character *c = &gs->characters[i];
        if (!c->used || c->lineage_id != lineage_id || c->status != GEN_STATUS_ACTIVE) continue;
        if (exclude_supreme && c->rank == GEN_RANK_SUPREME_COMMANDER) continue;
        if (gen_region_within_hops(w, mission_region, c->region, max_hops)) return 1;
    }
    return 0;
}

static gen_character *gen_find_any_living_member(gen_state *gs, uint32_t lineage_id, int exclude_supreme) {
    if (!gs) return NULL;
    for (uint32_t i = 0; i < gs->n_characters; i++) {
        gen_character *c = &gs->characters[i];
        if (!c->used || c->lineage_id != lineage_id || c->status != GEN_STATUS_ACTIVE) continue;
        if (exclude_supreme && c->rank == GEN_RANK_SUPREME_COMMANDER) continue;
        return c;
    }
    return NULL;
}

static int gen_is_descendant_of(gen_state *gs, uint32_t candidate_id, uint32_t ancestor_id) {
    gen_character *c = gen_char_find(gs, candidate_id);
    for (uint32_t guard = 0; c != NULL && guard < GEN_MAX_CHARACTERS; guard++) {
        if (c->parent_id == ancestor_id) return 1;
        if (c->parent_id == 0) break;
        c = gen_char_find(gs, c->parent_id);
    }
    return 0;
}

static void gen_stay(const om_world *w, gen_state *gs, uint32_t lineage_id, uint32_t mission_region,
                      om_selection_record *out_record) {
    gen_character *pick = gen_find_living_member_exact_hop(w, gs, lineage_id, mission_region, 0, 0);
    for (uint32_t hop = 1; !pick && hop <= OM_SELECTOR_PROXIMITY_HOPS; hop++)
        pick = gen_find_living_member_exact_hop(w, gs, lineage_id, mission_region, hop, 0);
    if (!pick) pick = gen_find_any_living_member(gs, lineage_id, 0);
    out_record->rotated = 0;
    if (pick) {
        out_record->commander_id = pick->id;
        gen_char_mark_main(pick);
    }
    gen_lineage *l = gen_lineage_find(gs, lineage_id);
    out_record->chapters_in_lineage = l ? l->chapter_count : 0;
    out_record->home_region_idx = l && l->n_history > 0 ? l->history[0] : mission_region;
}

static int gen_faction_survives(const uint32_t *surviving_regions, int32_t faction) {
    return faction >= 0 && (uint32_t)faction < OM_MAX_FACTIONS && surviving_regions[faction] > 0;
}

static gen_character *gen_pick_previous_candidate(const om_world *w, gen_state *gs, uint32_t mission_region,
                                                   const uint32_t *surviving_regions) {
    struct { gen_character *c; double score; } cands[GEN_MAX_SCAN_BUF];
    uint32_t n_cands = 0;
    if (!gs) return NULL;
    for (uint32_t li = 0; li < gs->n_lineages; li++) {
        gen_lineage *l = &gs->lineages[li];
        if (!l->used || l->chapter_count < 1) continue; /* R-058-02: played at least 1 chapter ago */
        uint32_t nearby = 0;
        for (uint32_t i = 0; i < gs->n_characters; i++) {
            gen_character *c = &gs->characters[i];
            if (!c->used || c->lineage_id != l->id || c->status != GEN_STATUS_ACTIVE) continue;
            if (surviving_regions && !gen_faction_survives(surviving_regions, c->faction)) continue;
            if (gen_region_within_hops(w, mission_region, c->region, OM_SELECTOR_PROXIMITY_HOPS)) nearby++;
        }
        if (nearby == 0) continue;
        double score = om_selector_score_previous_lineage(w, l->chapter_count, nearby);
        for (uint32_t i = 0; i < gs->n_characters && n_cands < GEN_MAX_SCAN_BUF; i++) {
            gen_character *c = &gs->characters[i];
            if (!c->used || c->lineage_id != l->id || c->status != GEN_STATUS_ACTIVE) continue;
            if (surviving_regions && !gen_faction_survives(surviving_regions, c->faction)) continue;
            if (!gen_region_within_hops(w, mission_region, c->region, OM_SELECTOR_PROXIMITY_HOPS)) continue;
            cands[n_cands].c = c;
            cands[n_cands].score = score;
            n_cands++;
        }
    }
    if (n_cands == 0) return NULL;
    double total = 0.0;
    for (uint32_t i = 0; i < n_cands; i++) total += cands[i].score;
    if (total <= 0.0) return cands[0].c;
    double roll = om_rng_draw((om_world *)w) * total;
    double cum = 0.0;
    for (uint32_t i = 0; i < n_cands; i++) {
        cum += cands[i].score;
        if (roll < cum) return cands[i].c;
    }
    return cands[n_cands - 1].c;
}

static int gen_pool_has_candidates(gen_state *gs, int pool) {
    if (!gs) return pool == GEN_POOL_UNRELATED;
    if (pool == GEN_POOL_PREVIOUS) return !gs->pool_previous_forced_empty;
    if (pool == GEN_POOL_NEMESIS) return !gs->pool_nemesis_forced_empty;
    return 1;
}

static uint32_t gen_resolve_candidate_for_pool(om_world *w, gen_state *gs, int pool, uint32_t mission_region,
                                                uint32_t new_lineage_id) {
    static const int PRIORITY[GEN_POOL_COUNT] = { GEN_POOL_PREVIOUS, GEN_POOL_NEMESIS, GEN_POOL_UNRELATED };
    int order[GEN_POOL_COUNT];
    order[0] = pool;
    int oi = 1;
    for (int i = 0; i < GEN_POOL_COUNT; i++) if (PRIORITY[i] != pool) order[oi++] = PRIORITY[i];
    for (int i = 0; i < GEN_POOL_COUNT; i++) {
        if (order[i] == GEN_POOL_PREVIOUS) {
            gen_character *c = gen_pick_previous_candidate(w, gs, mission_region, NULL);
            if (c) { c->lineage_id = new_lineage_id; return c->id; }
        } else if (order[i] == GEN_POOL_NEMESIS) {
            uint32_t n = om_selector_gather_nemesis_candidates(w, mission_region);
            if (n > 0 && gs) {
                double d = om_rng_draw(w);
                uint32_t idx = (uint32_t)(d * (double)n);
                if (idx >= n) idx = n - 1;
                gen_character *c = gen_char_find(gs, gs->nemesis_candidates[idx]);
                if (c) { c->lineage_id = new_lineage_id; return c->id; }
            }
        } else {
            uint32_t cid = om_selector_draw_unrelated(w, mission_region);
            gen_character *c = gen_char_find(gs, cid);
            if (c) {
                /* R-058-04: one lineage per unrelated rotation; drop the one the draw minted. */
                gen_lineage *stray = gen_lineage_find(gs, c->lineage_id);
                if (stray && c->lineage_id != new_lineage_id) stray->used = 0;
                c->lineage_id = new_lineage_id;
            }
            return cid;
        }
    }
    return 0;
}

static gen_character *gen_spawn_descendant_from_parent(om_world *w, gen_state *gs, uint32_t lineage_id,
                                                        uint32_t parent_id, uint64_t tick) {
    gen_character *p = gen_char_find(gs, parent_id);
    uint32_t region = p ? p->region : 0;
    double spread = om_rng_draw(w);
    if (spread < OM_LINEAGE_SPREAD_PROBABILITY && w) {
        uint32_t nbrs[GEN_REGION_CAP];
        uint32_t n_nbrs = om_region_neighbors(w, region, nbrs, GEN_REGION_CAP);
        uint32_t inhabited[GEN_REGION_CAP];
        uint32_t n_inhabited = 0;
        for (uint32_t i = 0; i < n_nbrs; i++) {
            if (nbrs[i] < w->n_regions && w->regions[nbrs[i]].population > 0.0)
                inhabited[n_inhabited++] = nbrs[i];
        }
        if (n_inhabited > 0) {
            double nd = om_rng_draw(w);
            uint32_t nidx = (uint32_t)(nd * (double)n_inhabited);
            if (nidx >= n_inhabited) nidx = n_inhabited - 1;
            region = inhabited[nidx];
        }
    }
    uint32_t id = gen_alloc_id(gs);
    gen_character *c = gen_char_alloc(gs, id);
    if (!c) return NULL;
    c->lineage_id = lineage_id;
    c->parent_id = parent_id;
    c->region = region;
    c->faction = p ? p->faction : -1;
    c->rank = GEN_RANK_LINEAGE_MEMBER;
    c->birth_tick = tick;
    c->generation = p ? p->generation + 1 : 0;
    c->status = GEN_STATUS_ACTIVE;
    gen_roll_name(w, c->name, sizeof(c->name));
    c->lifespan = gen_roll_lifespan(w);
    if (p) p->n_children++;
    return c;
}

static gen_force *gen_force_alloc(gen_state *gs, uint32_t mission_id) {
    if (!gs) return NULL;
    for (uint32_t i = 0; i < gs->n_force; i++)
        if (gs->force[i].used && gs->force[i].mission_id == mission_id) return &gs->force[i];
    if (gs->n_force >= GEN_MAX_FORCE_MISSIONS) return NULL;
    gen_force *f = &gs->force[gs->n_force++];
    memset(f, 0, sizeof(*f));
    f->used = 1;
    f->mission_id = mission_id;
    return f;
}

static gen_death_rec *gen_death_find_or_alloc(gen_state *gs, uint32_t commander_id) {
    if (!gs) return NULL;
    for (uint32_t i = 0; i < gs->n_deaths; i++)
        if (gs->deaths[i].used && gs->deaths[i].commander_id == commander_id) return &gs->deaths[i];
    if (gs->n_deaths >= GEN_MAX_DEATH_RECORDS) return NULL;
    gen_death_rec *d = &gs->deaths[gs->n_deaths++];
    memset(d, 0, sizeof(*d));
    d->used = 1;
    d->commander_id = commander_id;
    return d;
}

